B.ctT=new A.j(B.ju,["wfx_leg_shp3","wfp_legend","An arrow is a FLOW: data actually moves that way, and its label says WHAT moves. Containment is never drawn as an arrow.","text",480,256,600,40,10,12],t.M)
B.ctX=new A.j(B.ju,["wfx_leg_shp4","wfp_legend","Arrow labels are cut to 18 characters to fit the canvas label chip. The full wording is in the inventory doc.","text",480,308,600,40,10,12],t.M)
