B.d4c=new A.p("emojiColumn",B.t,"Optional column holding a leading emoji shown on each card.",B.f,null)
B.cN9=new A.p("rankColumn",B.t,'Column holding the manual within-lane sort rank (default "prioRank"); drag-reorder writes it.',B.f,null)
