B.cXo=new A.p("fileIcon",B.D,"File icon hint: image | draw | doc | sheet | note (default file).",B.f,null)
B.d_I=new A.p("newFileLabel",B.D,"Tooltip for the new-file button; may be a {lang: text} map.",B.f,null)
